CREATE TABLE business_contacts(contact_id TEXT PRIMARY KEY,site_id TEXT NOT NULL REFERENCES sites(site_id),organization TEXT NOT NULL,contact_scope TEXT NOT NULL CHECK(contact_scope IN ('site','company','group','project','external_procurement')),department TEXT NOT NULL,public_name TEXT,role TEXT NOT NULL,channel_type TEXT NOT NULL CHECK(channel_type IN ('work_phone','business_email','official_form','supplier_portal')),channel_value TEXT NOT NULL CHECK(length(trim(channel_value))>0),source_id TEXT NOT NULL,source_locator TEXT NOT NULL,publication_date TEXT,checked_on TEXT NOT NULL,verification_status TEXT NOT NULL CHECK(verification_status IN ('official_publication','statutory_disclosure','historical_project_publication')),use_boundary TEXT NOT NULL,FOREIGN KEY(site_id,source_id) REFERENCES site_sources(site_id,source_id),UNIQUE(organization,department,channel_type,channel_value));
CREATE VIEW v_business_contact_directory AS SELECT b.*,s.name AS site_name,s.province,s.city,e.title AS source_title,e.url AS source_url FROM business_contacts b JOIN sites s USING(site_id) JOIN sources e USING(source_id);
CREATE VIEW v_business_contact_counts AS SELECT contact_scope,channel_type,count(*) AS channel_count,count(DISTINCT site_id) AS linked_site_count FROM business_contacts GROUP BY 1,2;
