INSERT INTO membrane_retrofits (assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES ('RA047-02','R047-02','CN0201','chromium_design','screening',2,'分质回用及优化','汽提回收氨及电絮凝除铬优先；核实际处理后盐种、回用与浓水合规再比选NF/RO。','conditional','实际水质、投运、盐金属和浓水合法去向','INFERRED；W03S10；100t/a自制Cr2O3催化剂历史设计，未证实际；南厂站非本线生化站','非实际新增装置','投运、氨铬/盐、现行站及成本','分股采样、物料衡算、膜小试、全生命周期比选','源头减量、现有站优化',NULL,NULL,NULL,NULL,NULL,NULL,'现场参数不足，难度未知','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N047-01','CN0247','S047-01','一期首次工艺及源强','2.4、2.11.2、表2.11.2-1 pp152–154截图','征求意见原文镜像，分子筛12580.37、ROPAC24.8、贵金属C292m³/a；分子筛微电解/两级除硅/膜浓缩/蒸发结晶；综合EFBR+A/O+MBR。116.83m³/d是设计平均排水量非能力；喷淋正文0.533与表8、循环图43.2与表34.533不同，排放负荷与总量不闭合，原表值保留。加氢与贵金属A/B设计无工艺水，换产清洗编号回用；一级RO制水不计污水膜。2026建成报道非全设计投运证明。','WEB_SECONDARY','公开正文或截图核对，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N047-02','CN0201','W03S10','分股与汽提除铬细化','表3-18、3.9.3.2、图3-10','压滤11857.47及电絮凝100m³/d已录不重复。表48.39与正文57.03m³/d、纯水机日4.32及年3888.9不闭合。汽提pH>11，除氨60–95%设计，氨回收；电絮凝pH6.5出水调8.5；含铬污泥5t/a设计危废；南厂氢氧化钙除氟不设生化，对本项目调质；集团站后东猪龙河。截图超时。','WEB_PRIMARY','公开正文或截图核对，未归档原件','2026-11-28');
